/* Compact trainer telemetry: full-width meters and non-wrapping values. */
.partner.expedition-card{padding-left:23px;padding-right:23px}
.expedition-card .trainer-progress-caption{display:flex;align-items:center;justify-content:space-between;gap:5px;min-width:0;margin-bottom:5px}
.expedition-card .trainer-progress-caption>span{font:700 7px/1 var(--menu-font);letter-spacing:.2px;flex-shrink:0;color:#8ebbd0}
.expedition-card .trainer-progress-caption>b{font:700 9px/1.2 var(--menu-font);white-space:nowrap;letter-spacing:0;font-variant-numeric:tabular-nums;color:#d8eff9;min-width:0}
.expedition-card .roster-heading{display:grid;grid-template-columns:17px minmax(0,1fr) 14px;align-items:center;gap:5px;width:100%;height:30px;min-height:30px;padding:4px 0!important;border:0!important;border-image:none!important;border-bottom:1px solid #80bdd52a!important;border-radius:0;background:transparent!important;box-shadow:none;line-height:1}
.expedition-card .roster-heading>span{display:flex;align-items:center;gap:6px;font:750 10px var(--menu-font)}
