.expedition-card #expedition-team{max-height:176px;gap:6px;padding:3px 3px 3px 0;scrollbar-width:thin;scrollbar-color:#628fa866 transparent;scrollbar-gutter:stable}
.expedition-card button.expedition-pokemon{display:grid;grid-template-columns:25px minmax(0,1fr);align-items:center;gap:6px;min-height:65px;height:65px;padding:6px 5px!important;border:1px solid #4e76915c!important;border-image:none!important;border-radius:7px;background:linear-gradient(125deg,#163c55cc,#0d273ccd)!important;box-shadow:inset 0 1px 0 #d9f9ff12;text-align:left;overflow:hidden;transition:background .18s,border-color .18s}
.expedition-card button.expedition-pokemon:hover{transform:none;background:linear-gradient(125deg,#24536ccc,#16394fdd)!important;border-color:#80bfd5aa!important;filter:none}
.expedition-card button.expedition-pokemon.is-leader{border-color:#8dd9e3!important;box-shadow:inset 2px 0 0 #8dd9e3,inset 0 1px 0 #d8faff20}
.expedition-card .roster-portrait{width:25px;height:31px;min-width:25px;display:grid;place-items:center}
.expedition-card .roster-portrait img{width:28px;height:28px;object-fit:contain;image-rendering:pixelated!important}
.expedition-card .roster-details{display:block;min-width:0;width:100%}
.expedition-card .roster-name{display:flex;align-items:center;justify-content:space-between;gap:4px;min-width:0}
.expedition-card .roster-name strong{font:750 10px/13px var(--menu-font);white-space:nowrap;letter-spacing:-.2px}
.expedition-card .roster-level{gap:2px;white-space:nowrap;font:800 10px/13px var(--menu-font)}
.expedition-card .roster-level small{font:650 5px var(--menu-font)}
.expedition-card .roster-meter{display:grid;grid-template-columns:12px minmax(0,1fr);align-items:center;gap:2px 3px;margin-top:4px;min-width:0;width:100%}
.expedition-card .roster-meter .meter-caption{display:contents}
.expedition-card .roster-meter .meter-caption small{grid-column:1;font:650 6px/8px var(--menu-font)}
.expedition-card .roster-meter .meter-caption b{grid-column:2;font:650 8px/8px var(--menu-font);letter-spacing:0;white-space:nowrap;text-align:right;font-variant-numeric:tabular-nums;min-width:0;color:#c7deeb}
.expedition-card .roster-meter .meter-track{grid-column:1/-1;display:block;width:100%;height:3px;min-height:3px;box-sizing:border-box;border-radius:3px;background:#061b2b;overflow:hidden;border:0;box-shadow:0 1px 0 #8abed31a}
