.expedition-card .return-town{display:grid;grid-template-columns:15px minmax(0,1fr) 13px;align-items:center;gap:6px;width:100%;height:29px;min-height:29px;margin-top:8px;padding:5px 7px;border:1px solid #709aaf77;border-image:none;border-radius:7px;background:linear-gradient(#274b61,#153449);box-shadow:inset 0 1px 0 #d4f5ff1a}
.expedition-card .return-town span{font:650 9px/1 var(--menu-font);white-space:nowrap;text-align:left}
.expedition-card .return-town>svg.ui-icon{width:15px;height:15px;min-width:15px;color:#afe2f1}
