.expedition-card .roster-meter .meter-caption b{font-size:8.5px}

/* Recovery is a deliberate choice, presented as a calm expedition panel. */
#recovery-dialog{width:370px;box-sizing:border-box;padding:25px;border:1px solid #7694ac;border-radius:16px;background:radial-gradient(ellipse at 50% 0,#34526888,transparent 65%),linear-gradient(150deg,#173248,#0c1e31);color:#e6f2fc;box-shadow:inset 0 1px 0 #d9f6ff44,inset 0 0 0 4px #04142233,0 25px 90px #000a;overflow:hidden;text-align:center;font-family:var(--menu-font)}
#recovery-dialog::backdrop{background:#020b17bb;backdrop-filter:blur(5px)}
#recovery-dialog::before{content:'';position:absolute;top:0;left:calc(50% - 27px);width:54px;height:3px;background:#ff9682;border-radius:0 0 5px 5px}
.recovery-emblem{position:absolute;top:18px;left:20px;color:#91b9d1}.recovery-emblem .ui-icon{width:19px;height:19px}
.recovery-kicker{display:block;font:750 9px var(--menu-font);letter-spacing:1.2px;color:#91b2c8;margin:3px 0 17px}
.recovery-portrait{display:grid;place-items:center;width:82px;height:82px;box-sizing:border-box;margin:0 auto 14px;border-radius:50%;border:1px solid #b6cdd640;background:radial-gradient(circle,#45636a55,#132d4188);box-shadow:inset 0 1px 0 #e6faff22,0 5px 15px #030b2055}
.recovery-portrait img{width:72px;height:72px;object-fit:contain;image-rendering:pixelated;filter:saturate(.65) drop-shadow(0 3px 2px #02091499)}
#recovery-title{font:800 22px/1.25 var(--menu-font);margin:0 0 9px;letter-spacing:-.4px}
#recovery-description{font:12px/1.6 var(--menu-font);color:#9dbace;margin:0 0 20px}
.recovery-actions{display:grid;gap:9px}
.recovery-actions button{display:grid;grid-template-columns:21px minmax(0,1fr) 16px;gap:10px;align-items:center;text-align:left;padding:12px;border:1px solid #7193a65c;border-radius:9px;background:linear-gradient(#27465c,#173247);box-shadow:inset 0 1px 0 #d9faff1a;color:#d9edf7;cursor:var(--pw-cursor-interact,pointer);transition:background .18s,border-color .18s}
.recovery-actions button[data-recover=revive]{background:linear-gradient(#35685c,#224d46);border-color:#7dbba288;color:#e0f8ec}
.recovery-actions button:hover{border-color:#bce8f1;background:linear-gradient(#365d75,#21475f)}
.recovery-actions button[data-recover=revive]:hover{background:linear-gradient(#417c69,#2b6152);border-color:#b3e5c8}
.recovery-actions button:focus-visible{outline:2px solid #b4f2fb;outline-offset:3px}
.recovery-actions strong{display:block;font:750 13px var(--menu-font);margin-bottom:4px}
.recovery-actions small{display:block;font:10px/1.3 var(--menu-font);opacity:.75}
.recovery-actions .ui-icon{width:18px;height:18px;min-width:18px}
.recovery-actions .ui-icon:last-child{width:15px;height:15px;min-width:15px;opacity:.65}
#recovery-dialog footer{display:block;position:static;margin:17px 0 0;padding:0;border:0;background:none;font:10px var(--menu-font);color:#7295ad}
@media(prefers-reduced-motion:reduce){.recovery-actions button{transition:none}}
#recovery-dialog[open]{animation:recovery-panel-in .2s ease-out}
@keyframes recovery-panel-in{from{opacity:0;transform:translateY(8px) scale(.985)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){#recovery-dialog[open]{animation:none}}

/* Individual collection and independent shiny research. */
#collection-dialog .individual-controls{display:flex;gap:12px;padding:12px 0;flex-wrap:wrap}
.individual-controls label{display:flex;flex-direction:column;gap:6px;font:600 12px/1.4 'Segoe UI',sans-serif;color:var(--pw-muted)}
.individual-controls label:first-child{flex:1;min-width:220px}
.individual-controls input,.individual-controls select{min-height:38px;padding:8px 12px;background:#0a1b2b;color:var(--pw-ink);border:1px solid var(--pw-line);border-radius:7px;font:14px 'Segoe UI',sans-serif}
.individual-controls input:focus,.individual-controls select:focus{outline:2px solid var(--pw-blue);outline-offset:2px}
.individual-results{display:flex;justify-content:space-between;gap:16px;margin:8px 0 16px;font:12px 'Segoe UI',sans-serif;color:var(--pw-muted)}
#collection-dialog .individual-card{border:1px solid var(--pw-line);border-image:none;border-radius:10px;background:var(--pw-surface);box-shadow:var(--pw-depth);padding:16px;min-width:0}
#collection-dialog .individual-card.shiny-card{border-color:#947c45;background:radial-gradient(circle at 50% 24%,#ad843320,transparent 65%),var(--pw-surface)}
#collection-dialog .individual-card.shiny-card>small{color:var(--pw-yellow)}
.individual-quality{display:grid;gap:6px;margin:12px 0;font:12px 'Segoe UI',sans-serif;color:var(--pw-muted)}
.individual-quality span{display:flex;justify-content:space-between}.individual-quality b{color:var(--pw-ink)}
.individual-quality meter{width:100%;height:8px;appearance:none;border:none;background:#071421;border-radius:4px;overflow:hidden}
.individual-quality meter::-webkit-meter-bar{background:#071421;border:0;height:8px}
.individual-quality meter::-webkit-meter-optimum-value{background:linear-gradient(90deg,#409caf,var(--pw-blue));border-radius:4px}
#collection-dialog .individual-card button,#collection-dialog .individual-pagination button{border:1px solid #557b97;border-image:none;border-radius:7px;background:linear-gradient(#264960,#173249);box-shadow:inset 0 1px 0 #dbf7ff1a;padding:9px 12px;color:var(--pw-ink);transition:background .18s,border-color .18s}
#collection-dialog .individual-card button:hover,#collection-dialog .individual-pagination button:hover{border-color:var(--pw-blue);background:linear-gradient(#335f7a,#22445e)}
.individual-pagination{display:flex;justify-content:space-between;margin:16px 0 0;gap:12px}.individual-pagination button{display:flex;gap:8px;align-items:center}
.individual-pagination .ui-icon{width:16px;height:16px}.individual-empty{color:var(--pw-muted);padding:20px}
.individual-iv-value{color:var(--pw-blue);white-space:nowrap}.individual-iv-value small{color:var(--pw-muted)}

.expedition-pokemon.is-shiny .roster-portrait{border-color:#d7b76e;box-shadow:inset 0 0 9px #ffd46d18,0 0 0 1px #d7b76e44}
.expedition-pokemon.is-shiny .roster-name strong{color:#f5cd7d}

/* Persistent capture research within the existing collection. */
.collection-modes{display:flex;gap:8px;padding:8px 0}
#collection-dialog .collection-modes button{border:1px solid var(--pw-line);border-image:none;border-radius:7px;background:linear-gradient(#203b50,#142a3d);padding:10px 16px;color:var(--pw-muted);font:600 13px 'Segoe UI',sans-serif;box-shadow:inset 0 1px 0 #ffffff0d;transition:border-color .18s,color .18s,background .18s}
#collection-dialog .collection-modes button[aria-pressed=true]{border-color:var(--pw-blue);color:var(--pw-ink);background:linear-gradient(#285269,#183a50);box-shadow:inset 0 -2px 0 var(--pw-blue)}
.individual-controls label[hidden]{display:none}
#collection-dialog #individual-cards.capture-history-list{display:grid;grid-template-columns:1fr;gap:10px}
.capture-history-row{display:grid;grid-template-columns:48px minmax(0,1fr) auto;align-items:center;gap:8px 14px;padding:13px 16px;border:1px solid var(--pw-line);border-radius:10px;background:var(--pw-surface);box-shadow:var(--pw-depth);font:14px/1.4 'Segoe UI',sans-serif}
.capture-history-row>img{width:40px;height:40px;object-fit:contain;image-rendering:pixelated}
.capture-record-heading,.capture-record-result{display:grid;gap:3px}.capture-record-heading strong{color:var(--pw-ink)}
.capture-record-heading small,.capture-record-result small{color:var(--pw-muted);font-size:12px}
.capture-record-result{text-align:right}.capture-record-result.caught b{color:var(--pw-green)}.capture-record-result.escaped b{color:var(--pw-red)}
.capture-history-row.shiny-record{border-color:#947c45}.shiny-record .capture-record-heading strong{color:var(--pw-yellow)}
.capture-history-row details{grid-column:2/-1}.capture-history-row summary{color:var(--pw-blue);font-size:12px;cursor:var(--pw-cursor-interact,pointer);width:fit-content;padding:3px 0}
.capture-history-row summary:focus-visible{outline:2px solid var(--pw-blue);outline-offset:3px;border-radius:3px}
.capture-iv-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:12px 0 2px}
.capture-iv-grid>span{display:flex;justify-content:space-between;gap:8px;padding:7px 9px;background:#071a2a;border:1px solid #38506466;border-radius:5px;font-size:12px;color:var(--pw-muted)}
.capture-iv-grid b{color:var(--pw-ink);white-space:nowrap}

#collection-dialog .individual-controls label{margin:0;align-items:stretch;text-align:left}
#collection-dialog .individual-controls label:not(:first-child){width:175px}
#collection-dialog .individual-controls input,#collection-dialog .individual-controls select{width:100%;max-width:none;box-sizing:border-box}
.individual-progress-panel{padding:14px;margin-bottom:14px;border:1px solid #52829a88;border-radius:10px;background:linear-gradient(135deg,#23475a77,#0b203455);box-shadow:inset 0 1px 0 #c0eeff16}
.individual-xp-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;font-size:13px}.individual-xp-heading strong{color:var(--pw-blue);font-size:18px}.individual-xp-heading span{color:#c2dce8}
.individual-progress-panel progress{appearance:none;display:block;width:100%;height:7px;margin:9px 0 6px;border:0;border-radius:5px;overflow:hidden;background:#061523}.individual-progress-panel progress::-webkit-progress-bar{background:#061523}.individual-progress-panel progress::-webkit-progress-value{background:linear-gradient(90deg,#3797b8,#83e2ec)}.individual-progress-panel progress::-moz-progress-bar{background:linear-gradient(90deg,#3797b8,#83e2ec)}
.individual-progress-panel>p{margin:0;font-size:11px;color:var(--pw-muted)}.individual-next-move{display:grid;grid-template-columns:1fr auto;gap:4px 12px;padding-top:13px}.individual-next-move small{grid-column:1/-1;color:#91bfd0;font-size:9px;letter-spacing:.8px}.individual-next-move strong{font-size:13px}.individual-next-move span{color:#b2cbd9;font-size:11px;align-self:center}
.individual-evolution{display:flex;align-items:center;gap:12px;margin-top:13px;padding-top:12px;border-top:1px solid #7299ad33}.individual-evolution>img{width:44px;height:44px;object-fit:contain;image-rendering:pixelated}.individual-evolution>div{display:grid;gap:4px;flex:1}.individual-evolution small{font-size:9px;color:#b0cea3;letter-spacing:.8px}.individual-evolution strong{font-size:14px}.individual-evolution span{font-size:11px;color:#adbfce}
#pokemon-details-dialog .individual-evolution button{color:#d9f1ce;background:linear-gradient(#375444,#23392f)!important;border-color:#80ae7688!important}#pokemon-details-dialog .individual-evolution button:disabled{opacity:.55;cursor:not-allowed}

/* Individual collection planning; no stretched raster frames. */
.collection-organizer{display:flex;align-items:stretch;gap:12px;margin:5px 0 15px}.collection-organizer[hidden]{display:none}
#collection-dialog .collection-organizer button{border:1px solid var(--pw-line);border-image:none;background:linear-gradient(#26465c,#173047);border-radius:7px;box-shadow:inset 0 1px 0 #ffffff12;padding:8px 12px;color:var(--pw-ink);font:600 12px 'Segoe UI',sans-serif;display:inline-flex;align-items:center;justify-content:center;gap:6px}
#collection-dialog .collection-organizer button:disabled{opacity:.5;cursor:not-allowed}#collection-dialog .collection-organizer button[aria-pressed=true]{border-color:var(--pw-yellow);color:var(--pw-yellow)}
#collection-selection{flex:1;display:flex;align-items:center;gap:8px;padding:10px 12px;border:1px solid #47677d;border-radius:8px;background:#0b2337;min-width:0}
#collection-selection>div{display:grid;gap:4px;flex:1;min-width:0}#collection-selection b{font-size:12px;color:var(--pw-ink)}#collection-selection span{font-size:11px;line-height:1.5;color:var(--pw-muted)}
#collection-dialog .individual-card.comparison-selected{border-color:var(--pw-blue);box-shadow:var(--pw-depth),inset 0 0 0 1px #73d6e944}
.individual-card-tools{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}#collection-dialog .individual-card-tools button{display:flex;align-items:center;justify-content:center;gap:5px;min-width:0;padding:8px 5px;font:600 11px 'Segoe UI',sans-serif}
#collection-dialog .individual-card-tools button[aria-pressed=true]{border-color:var(--pw-blue);color:var(--pw-blue)}#collection-dialog .individual-card-tools button[data-favorite-uid][aria-pressed=true]{border-color:#ad935a;color:var(--pw-yellow)}
.individual-card-tools .ui-icon,.collection-organizer .ui-icon{width:15px;height:15px;flex-shrink:0}
#individual-comparison-dialog{width:720px;max-width:94vw;max-height:92dvh;box-sizing:border-box;padding:22px 24px;border:2px solid #63869e;border-radius:14px;background:radial-gradient(ellipse at 0 0,#284e6a66,transparent 65%),linear-gradient(135deg,#142f48,#0b2034);color:var(--pw-ink);box-shadow:inset 0 0 0 3px #07162666,inset 0 1px 0 #dcfaff33,0 25px 80px #000b;font:13px/1.4 'Segoe UI',sans-serif}
#individual-comparison-dialog[open]{display:flex;flex-direction:column}#individual-comparison-dialog::backdrop{background:#020b1bd9;backdrop-filter:blur(4px)}
#individual-comparison-dialog>header,#individual-comparison-dialog>footer{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-shrink:0}
#individual-comparison-dialog>header{border-bottom:1px solid #8cc8de33;padding-bottom:15px}#individual-comparison-dialog>header small{font-size:9px;letter-spacing:1px;color:#9dbfd2}#individual-comparison-dialog h2{font-size:23px;line-height:1.3;margin:5px 0 0}
#individual-comparison-dialog button{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:34px;padding:7px 12px;border:1px solid #557b97;border-radius:7px;background:linear-gradient(#264960,#173249);color:var(--pw-ink);font:600 12px 'Segoe UI',sans-serif;box-shadow:inset 0 1px 0 #dbf7ff1a;cursor:var(--pw-cursor-interact,pointer);transition:border-color .18s,background .18s}
#individual-comparison-dialog button:hover{border-color:var(--pw-blue);background:linear-gradient(#335f7a,#22445e)}#individual-comparison-dialog button:disabled{opacity:.5;cursor:not-allowed}#individual-comparison-dialog button:focus-visible{outline:2px solid var(--pw-blue);outline-offset:3px}#individual-comparison-dialog .ui-icon{width:16px;height:16px}
.comparison-scroll{overflow:auto;min-height:0;padding:16px 0;scrollbar-width:thin;scrollbar-color:#75b5c9 #0a2540}.comparison-partners{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.comparison-partner{display:grid;justify-items:center;gap:5px;padding:14px;border:1px solid var(--pw-line);border-radius:10px;background:var(--pw-surface);box-shadow:var(--pw-depth)}.comparison-partner>img{width:54px;height:54px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 4px 4px #0007)}.comparison-partner small,.comparison-partner>span{font-size:11px;color:var(--pw-muted)}.comparison-partner h3{font-size:17px;margin:0}.comparison-partner>b{color:var(--pw-blue)}.comparison-partner.shiny{border-color:#947c45}.comparison-partner.shiny h3{color:var(--pw-yellow)}.comparison-partner>button{margin-top:5px;width:100%}
.comparison-tabs{display:flex;gap:8px;margin:15px 0 10px}.comparison-tabs>button{flex:1}#individual-comparison-dialog .comparison-tabs button[aria-pressed=true]{border-color:var(--pw-blue);box-shadow:inset 0 -2px 0 var(--pw-blue)}
.comparison-context p{font-size:11px;line-height:1.6;color:var(--pw-muted);margin:8px 0 12px}#individual-comparison-dialog .comparison-context label{display:flex;justify-content:flex-start;gap:8px;margin:0;color:var(--pw-ink);font-size:12px}#comparison-equal-level{accent-color:var(--pw-blue);width:15px;height:15px;margin:0}
.comparison-table{width:100%;border-collapse:collapse;table-layout:fixed}.comparison-table th,.comparison-table td{text-align:left;padding:10px 12px;border-bottom:1px solid #38506488}.comparison-table th{font-size:12px;color:#b8d2e2}.comparison-table thead th:first-child{width:27%}.comparison-table thead small{display:block;font-size:10px;color:var(--pw-muted);margin-top:3px}.comparison-table td>div{display:flex;align-items:center;justify-content:space-between;gap:8px}.comparison-table td b{font-size:15px}.comparison-table td small{color:var(--pw-green);font-size:11px}.comparison-higher b{color:var(--pw-green)}
.comparison-table meter{display:block;width:100%;height:6px;margin-top:5px;appearance:none;background:#071725;border-radius:4px;border:0}.comparison-table meter::-webkit-meter-bar{border:0;background:#071725}.comparison-table meter::-webkit-meter-optimum-value{background:linear-gradient(90deg,#3c86a4,#73d6e9)}.comparison-table meter::-moz-meter-bar{background:#73d6e9}
#individual-comparison-dialog>footer{padding-top:13px;border-top:1px solid #8cc8de33}#individual-comparison-dialog>footer span{font-size:11px;color:var(--pw-muted)}

#individual-comparison-dialog .comparison-partner{padding:10px;gap:3px}#individual-comparison-dialog .comparison-partner>img{width:44px;height:44px}#individual-comparison-dialog .comparison-table th,#individual-comparison-dialog .comparison-table td{padding:8px 12px}#individual-comparison-dialog .comparison-table meter{margin-top:4px}

#dex-research-summary{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:8px 0}
#collection-dialog .dex-research-form{display:grid;gap:8px;padding:14px 16px;border:1px solid var(--pw-line);border-image:none;border-radius:9px;background:var(--pw-surface);box-shadow:var(--pw-depth);text-align:left;color:var(--pw-ink)}
.dex-research-form>span{display:flex;align-items:center;justify-content:space-between;gap:10px}.dex-research-form b{font-size:13px}.dex-research-form strong{font-size:20px;color:var(--pw-blue)}.dex-research-form strong small{font-size:11px;font-weight:400;color:var(--pw-muted)}.dex-research-form>small{font-size:11px;color:var(--pw-muted)}
#collection-dialog .dex-research-form[aria-pressed=true]{border-color:var(--pw-blue);box-shadow:var(--pw-depth),inset 0 -2px 0 var(--pw-blue)}#collection-dialog .dex-research-form.shiny[aria-pressed=true]{border-color:var(--pw-yellow);box-shadow:var(--pw-depth),inset 0 -2px 0 var(--pw-yellow)}.dex-research-form.shiny strong{color:var(--pw-yellow)}
.dex-research-form progress{display:block;appearance:none;width:100%;height:6px;border:0;border-radius:4px;overflow:hidden;background:#071725}.dex-research-form progress::-webkit-progress-bar{background:#071725}.dex-research-form progress::-webkit-progress-value{background:#73d6e9}.dex-research-form progress::-moz-progress-bar{background:#73d6e9}.dex-research-form.shiny progress::-webkit-progress-value{background:#f5cd7d}.dex-research-form.shiny progress::-moz-progress-bar{background:#f5cd7d}
#collection-dialog .dex-find-hunt{display:flex;align-items:center;justify-content:center;gap:6px}.dex-find-hunt .ui-icon{width:14px;height:14px}
:root{--supply-accent:var(--pw-blue)}
#collection-dialog[data-view="bag"]{width:min(850px,94vw);border:1px solid #4c7087;border-image:none;border-radius:12px;padding:20px;background:radial-gradient(ellipse at top right,#24608c35,transparent 60%),var(--pw-surface);box-shadow:var(--pw-depth),0 25px 90px #000a}
#collection-dialog[data-view="bag"] .dialog-header{background:none;border:0;border-bottom:1px solid var(--pw-line);border-radius:0;padding:0 0 16px!important}
.supply-wallet{display:flex;align-items:center;gap:12px;padding:14px 16px;margin:16px 0;background:#091c2a;border:1px solid #3a5669;border-radius:8px}
.supply-wallet img{width:40px;height:40px;object-fit:contain;image-rendering:auto}
.supply-wallet small{display:block;color:var(--pw-muted);font-size:9px;letter-spacing:1px}
.supply-wallet strong{font-size:25px;color:var(--pw-yellow)}
.supply-wallet p{margin:0 0 0 auto;color:var(--pw-ink);font-size:13px;text-align:right;line-height:1.6}
.supply-wallet p span{color:var(--pw-muted);font-size:11px}
.bag-grid.supply-grid{gap:12px}
.bag-grid.supply-grid article{border:1px solid #3f5e75;border-image:none;border-radius:10px;padding:14px;gap:8px;background:radial-gradient(ellipse at 50% 20%,#5bb5d51a,transparent 60%),var(--pw-surface);box-shadow:inset 0 1px #ffffff14;transition:border-color .18s}
.bag-grid.supply-grid article:hover{border-color:#6b95aa}
.bag-grid.supply-grid article>span{height:80px}
.bag-grid.supply-grid article>span .menu-art{width:74px;height:74px;object-fit:contain}
.supply-grid h3{font-size:17px;margin:0}
.supply-state{align-self:flex-start;color:var(--pw-green);font-size:10px;background:#9aca7b0c;border:1px solid #9aca7b35;border-radius:5px;padding:4px 7px}
.supply-empty .supply-state{color:var(--pw-red);background:#f988700d;border-color:#f9887045}
.supply-count{font-size:26px;color:var(--pw-ink)}
.supply-count small{font-size:10px;font-weight:400;color:var(--pw-muted)}
.supply-grid p{min-height:56px;margin:4px 0;font-size:11px;line-height:1.6}
.supply-policy{width:100%;display:flex;justify-content:space-between;gap:5px;font-size:10px;color:var(--pw-muted);border-top:1px solid #38506480;padding-top:10px}
.supply-policy b{color:var(--pw-blue);font-weight:600}
.supply-notice{font-size:11px;line-height:1.5;text-align:left;min-height:38px;color:var(--pw-muted);width:100%}
.supply-empty .supply-notice{color:#ffb299}
#collection-dialog .bag-grid.supply-grid button{border:1px solid #608496;border-image:none;border-radius:6px;background:linear-gradient(#30516a,#1b364a);height:auto;min-height:44px;padding:8px;display:flex;flex-direction:column;gap:3px;align-items:center;color:var(--pw-ink);font:600 12px var(--pw-font);box-shadow:inset 0 1px #ffffff16,0 2px #091725}
#collection-dialog .bag-grid.supply-grid button span{font-size:10px;font-weight:400;color:var(--pw-yellow)}
#collection-dialog .bag-grid.supply-grid button:hover:not(:disabled){border-color:var(--pw-blue);background:linear-gradient(#3a657e,#25485e)}
#collection-dialog .bag-grid.supply-grid button:disabled{opacity:1;cursor:not-allowed;background:#192b3a;border-color:#384f60;color:#8a9fac;box-shadow:none}
#collection-dialog .bag-grid.supply-grid button:disabled span{color:#8a9fac}
.supply-shortfall{font-size:10px;min-height:15px;color:var(--pw-muted)}
.genetics-individual,.genetics-intro,.genetics-guide>section{background:var(--pw-surface);border:1px solid #3e5c73;border-radius:9px;padding:14px}
.genetics-summary{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}
.genetics-summary>div{display:grid;gap:5px}.genetics-summary small,.genetics-guide>section>small{font-size:9px;color:var(--pw-muted);letter-spacing:.8px}.genetics-summary strong{font-size:18px;color:var(--pw-blue)}.genetics-summary>b{font-size:22px;color:var(--pw-yellow)}.genetics-summary>b small{font-size:11px;letter-spacing:0}
[data-details-view="genetics"] p{color:var(--pw-muted);font:12px/1.6 var(--pw-font);margin:8px 0}
.genetics-rows{display:grid;gap:5px;margin-top:14px}
.genetics-row{display:grid;grid-template-columns:110px 58px minmax(60px,1fr) 112px;align-items:center;gap:10px;border-bottom:1px solid #38506465;padding:8px 0;font-size:12px}
.genetics-row>strong{color:var(--pw-ink);font-weight:600}.genetics-row>span{color:var(--pw-blue);font-weight:700}.genetics-row small{font-size:10px;color:var(--pw-muted);font-weight:400}
.genetics-row progress{appearance:none;width:100%;height:6px;border:0;border-radius:5px;overflow:hidden;background:#091a28}
.genetics-row progress::-webkit-progress-bar{background:#091a28;border-radius:5px}.genetics-row progress::-webkit-progress-value{background:linear-gradient(90deg,#4aacc7,#9de4eb);border-radius:5px}.genetics-row progress::-moz-progress-bar{background:#73d6e9;border-radius:5px}
.genetics-row>b{color:var(--pw-green);text-align:right;font-size:13px}
[data-details-view="genetics"] .genetics-caption{font-size:11px;margin-bottom:0}
.genetics-guide{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}
.genetics-guide h3{font:700 14px var(--pw-font);margin:7px 0;color:var(--pw-ink)}
.genetics-capture-value{font-size:25px;font-weight:750;color:var(--pw-yellow);margin:10px 0}
.genetics-capture-ranges{display:grid;gap:7px;margin:12px 0;font-size:12px}.genetics-capture-ranges>span{display:flex;justify-content:space-between;color:var(--pw-muted)}.genetics-capture-ranges b{color:var(--pw-yellow)}
.pokemon-details-content:has([data-details-tab="genetics"][aria-pressed="true"]) .individual-progress-panel,.pokemon-details-content:has([data-details-tab="genetics"][aria-pressed="true"]) .pokemon-hunt-info{display:none}
.pokemon-details-content:has(.genetics-intro):has([data-details-tab="genetics"][aria-pressed="true"]) .stat-level-control{display:none}
