.assistant-policy-summary{font-size:11px;line-height:1.6;color:var(--pw-blue);margin:12px 0;border-left:2px solid var(--pw-blue);padding-left:9px}
.assistant-stock{display:flex;align-items:center;gap:9px;margin:12px 0}.assistant-stock img{width:35px;height:35px;object-fit:contain;image-rendering:auto}.assistant-stock>div{display:grid;gap:4px}.assistant-stock strong{font-size:13px;color:var(--pw-ink)}.assistant-stock small{font-size:10px;line-height:1.5;color:var(--pw-muted)}.assistant-stock small.assistant-stock-empty{color:var(--pw-red)}
#panel-helper.drawer button.full{border:1px solid #52758e;border-image:none;border-radius:6px;background:linear-gradient(#2c4d65,#17354a);box-shadow:inset 0 1px #d0f7ff17,0 2px #081724;padding:8px;font-size:12px;min-height:35px;color:var(--pw-ink)}
