.dex-counter>strong{font:750 23px/1 var(--pw-font);color:var(--pw-blue);font-variant-numeric:tabular-nums}.dex-counter strong small{font:10px var(--pw-font);color:var(--pw-muted);margin-left:3px}.dex-counter>span{font:11px var(--pw-font);color:#b4cbd9}.dex-counter.caught>strong{color:var(--pw-green)}.dex-counter.missing>strong{color:var(--pw-yellow)}
