#collection-dialog.compact-dex-dialog #individual-cards{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));grid-auto-rows:108px;align-content:start;gap:8px;overflow:auto;min-height:0;flex:1;padding:2px 7px 5px 2px;scrollbar-width:thin;scrollbar-color:#54778d #0c2031}
.dex-tile{position:relative;min-width:0;border:1px solid #3b566c;border-bottom-color:color-mix(in srgb,var(--dex-type) 60%,#3b566c);border-radius:9px;background:radial-gradient(ellipse at 50% 25%,color-mix(in srgb,var(--dex-type) 10%,transparent),transparent 75%),#10283b;box-shadow:inset 0 1px #c2e5f20c;transition:border-color .18s,box-shadow .18s}
#collection-dialog .dex-tile-open{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;width:100%;height:100%;min-height:0;padding:7px 3px 5px;background:none!important;border:0!important;border-image:none!important;border-radius:8px;box-shadow:none!important;cursor:var(--pw-cursor-interact,pointer);transform:none}
#collection-dialog .dex-tile-open img{width:54px;height:54px;max-width:100%;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 3px 2px #0006);transition:transform .18s,filter .18s;margin:0}
#collection-dialog .dex-tile-open>small{font:9px/1 var(--pw-font);color:#91b3c7}
#collection-dialog .dex-tile-open>strong{font:650 11px/1.15 var(--pw-font);color:var(--pw-ink);width:100%;white-space:normal;overflow-wrap:anywhere;min-height:25px;display:grid;place-items:center;text-align:center}
.dex-tile-status{position:absolute;top:6px;right:6px;display:grid;place-items:center;width:15px;height:15px;color:#7c9bb0}.dex-tile-status .ui-icon{width:14px;height:14px}.is-caught .dex-tile-status{color:var(--pw-green)}.is-seen .dex-tile-status{color:var(--pw-blue)}
#collection-dialog .is-unseen .dex-tile-open img{filter:brightness(0) opacity(.38);transform:none}.dex-tile.is-shiny{border-color:#8b7548;background:radial-gradient(at 50% 20%,#ba943419,transparent 80%),#172a3b}
