.dex-tile-map .ui-icon{width:13px;height:13px}
.dex-tile:hover,.dex-tile:focus-within{border-color:var(--pw-blue);box-shadow:inset 0 0 0 1px #73d6e929,0 0 10px #73d6e913}
#collection-dialog .dex-tile:hover .dex-tile-open img{transform:translateY(-2px)}
#collection-dialog .dex-tile:hover .dex-tile-map,#collection-dialog .dex-tile:focus-within .dex-tile-map{opacity:1}
#collection-dialog.compact-dex-dialog .individual-pagination{display:none}
