#collection-dialog.compact-dex-dialog .individual-controls input,#collection-dialog.compact-dex-dialog .individual-controls select{width:100%;min-width:0;max-width:100%;box-sizing:border-box}
#collection-dialog.compact-dex-dialog #individual-cards{grid-auto-rows:94px}
