 --pw-window-bg:linear-gradient(125deg,#667b9720 0 12%,transparent 12% 74%,#8671b011 74%),radial-gradient(ellipse at 0% 0%,#38607c66,transparent 55%),radial-gradient(ellipse at 100% 100%,#7e527929,transparent 55%),linear-gradient(145deg,#202e47fa,#111c30fc 75%);
 --pw-window-shadow:inset 0 0 0 3px #0a1326,inset 0 0 0 4px #637c9b70,inset 0 7px 22px #bbd8ff0a,0 0 0 1px #081123,0 20px 60px #020812a0;
