#hunt-analyzer-dialog .analyzer-drop-list{max-width:100%;scroll-snap-type:none}
#hunt-analyzer-dialog .analyzer-drop-list article{display:grid;grid-template-columns:36px minmax(0,1fr) auto auto;gap:8px;align-items:center}
#hunt-analyzer-dialog .analyzer-drop-list article>img{width:34px;height:34px;object-fit:contain}
#hunt-analyzer-dialog .analyzer-drop-list article>span{min-width:0}
#hunt-analyzer-dialog .analyzer-actions{position:static;margin:12px 0 4px}
@media(max-width:640px){body.prisma-theme #hunt-analyzer-dialog[open]{max-height:calc(100dvh - 20px);padding:16px}#hunt-analyzer-dialog .analyzer-content{padding-right:4px}}
/* Species collection scrolls independently; cards keep their full text height. */
#mastery-dialog.mastery-v2 .ms-species-grid{overflow-y:auto;overflow-x:hidden;grid-template-rows:none;grid-auto-rows:144px;align-content:start;min-height:0;padding:5px;scrollbar-gutter:stable;overscroll-behavior:contain}
#mastery-dialog.mastery-v2 .ms-species{display:grid;grid-template-rows:12px 46px 17px 13px 5px 13px;align-content:center;justify-items:center;gap:3px;padding:8px 5px;min-height:144px;box-sizing:border-box;overflow:hidden;transform:none!important;transition:border-color .15s,background .15s}
#mastery-dialog.mastery-v2 .ms-species img{width:44px;height:44px}
#mastery-dialog.mastery-v2 .ms-species strong{display:block;font-size:10px;line-height:16px;min-height:16px;margin:0}
#mastery-dialog.mastery-v2 .ms-species .ms-card-types{display:block;font-size:8px;line-height:12px;max-width:100%;overflow:hidden;text-overflow:ellipsis}
#mastery-dialog.mastery-v2 .ms-species>small{line-height:12px;white-space:nowrap;font-size:8px}
#mastery-dialog.mastery-v2 .ms-species[aria-pressed=true]{box-shadow:inset 0 0 0 1px #8ee6f0;background:linear-gradient(145deg,#28576a,#20364c)}
#mastery-dialog.mastery-v2 .ms-species:focus-visible{outline:2px solid #f6d891;outline-offset:-3px}
#mastery-dialog.mastery-v2 .ms-pagination{min-height:20px}
@media(max-width:700px){#mastery-dialog.mastery-v2 .ms-library{min-height:0}#mastery-dialog.mastery-v2 .ms-species-grid{min-height:0;max-height:440px;height:440px;flex:none;grid-template-rows:none;grid-auto-rows:144px}#mastery-dialog.mastery-v2 .ms-pagination{font-size:9px}}

#game-chat .chat-message .chat-player-name.is-vip{color:#65d9ff;text-shadow:0 0 7px #40bfff33}
#game-chat .chat-message .chat-player-name.is-vip-ruby{color:#ff647b;text-shadow:0 0 7px #ff315633}
#game-chat .chat-player-name .vip-nickname-badge{margin-left:0;margin-right:5px;width:17px;height:17px;vertical-align:-3px}
